32	type CoordinatorConfig struct {
33		// Object store for metadata persistence
34		ObjectStore *s3metastore.S3MetaStore
35	
36		// Enable version file functionality
37		VersionFileEnabled bool
38	
39		// Heap service configuration (optional)
40		HeapServiceEnabled          bool
