47	func NewCoordinator(ctx context.Context, config CoordinatorConfig) (*Coordinator, error) {
48		s := &Coordinator{
49			ctx:         ctx,
50			objectStore: config.ObjectStore,
51		}
52	
53		// catalog
54		txnImpl := dbcore.NewTxImpl()
55		metaDomain := dao.NewMetaDomain()
56		s.catalog = *NewTableCatalog(txnImpl, metaDomain, s.objectStore, config.VersionFileEnabled)
57	
58		// Initialize heap client if enabled
59		if config.HeapServiceEnabled {
60			memberlistStore, err := memberlist_manager.NewCRMemberlistStoreFromK8s(
61				config.KubernetesNamespace,
62				config.LogServiceMemberlistName,
63			)
64			if err != nil {
65				log.Error("Failed to create memberlist store", zap.Error(err))
66				return nil, err
67			}
68	
69			hasher, err := GetHasherFromString(config.HeapServiceAssignmentHasher)
70			if err != nil {
71				log.Error("Failed to get hasher from config", zap.Error(err))
72				return nil, err
73			}
74	
75			s.heapClient = NewGrpcHeapClient(memberlistStore, config.HeapServicePort, hasher)
76			log.Info("Heap service client initialized",
77				zap.String("memberlist", config.LogServiceMemberlistName),
78				zap.Int("port", config.HeapServicePort),
79				zap.String("hasher", config.HeapServiceAssignmentHasher))
80		}
81	
82		return s, nil
83	}
