// UpdateCompletionOffsetAndHeapEntry atomically advances the completion offset for the
// attached function and marks its heap entry as pending. The WHERE guard ensures the
// offset can only move forward: if newOffset is not strictly greater than the stored
// completion_offset, no rows are updated and common.ErrAttachedFunctionOffsetWouldRegress
// is returned.
func (s *attachedFunctionDb) UpdateCompletionOffsetAndHeapEntry(id uuid.UUID, collectionID string, newOffset int64) error {
	result := s.db.Model(&dbmodel.AttachedFunction{}).
		Where("id = ?", id).
		Where("input_collection_id = ?", collectionID).
		Where("completion_offset < ?", newOffset).
		Updates(map[string]interface{}{
			"completion_offset":  newOffset,
			"heap_entry_pending": true,
			"updated_at":         time.Now(),
		})

	if result.Error != nil {
		log.Error("UpdateCompletionOffsetAndHeapEntry failed",
			zap.Error(result.Error),
			zap.String("id", id.String()),
			zap.String("collection_id", collectionID),
			zap.Int64("new_offset", newOffset))
		return result.Error
	}

	if result.RowsAffected == 0 {
		// The guard clause prevented the update because the offset would regress
		// (or stay the same).
		log.Warn("UpdateCompletionOffsetAndHeapEntry: offset would regress",
			zap.String("id", id.String()),
			zap.String("collection_id", collectionID),
			zap.Int64("new_offset", newOffset))
		return common.ErrAttachedFunctionOffsetWouldRegress
	}

	return nil
}

