// TryFinishAsyncAttachedFunctionInvocation attempts to finalize an async attached
// function's invocation by advancing its completion offset atomically.
//
// The work happens inside a single database transaction:
//  1. Fetch the attached function by ID (with a row lock).
//  2. Retrieve the associated function record.
//  3. Retrieve the collection record.
//  4. Call UpdateCompletionOffsetAndHeapEntry to advance the offset.
//
// If the collection's log position is ahead of the new completion offset, the
// invocation cannot be finalized and a NeedsRepair result is returned (carrying the
// current collection log offset). Otherwise a Success result is returned with the new
// completion offset. If advancing the offset would cause it to regress, the underlying
// UpdateCompletionOffsetAndHeapEntry returns common.ErrAttachedFunctionOffsetWouldRegress,
// which is propagated to the caller.
func (s *Coordinator) TryFinishAsyncAttachedFunctionInvocation(ctx context.Context, req *coordinatorpb.TryFinishAsyncAttachedFunctionInvocationRequest) (*coordinatorpb.TryFinishAsyncAttachedFunctionInvocationResponse, error) {
	log := log.With(zap.String("method", "TryFinishAsyncAttachedFunctionInvocation"))

