			}
		} else {
			response = &coordinatorpb.TryFinishAsyncAttachedFunctionInvocationResponse{
				Result: &coordinatorpb.TryFinishAsyncAttachedFunctionInvocationResponse_Success{
					Success: &coordinatorpb.TryFinishAsyncAttachedFunctionInvocationResponse_SuccessResult{
						UpdatedCompletionOffset: req.NewCompletionOffset,
					},
				},
			}
		}

